-- Migration: Alterar charset da tabela email_templates para suportar emojis e inserir templates do Carnê
-- Esses templates ficam visíveis em Configurações > Criar E-mail > Templates Salvos

ALTER TABLE email_templates CONVERT TO CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

INSERT INTO email_templates (evento_id, nome, assunto, corpo_html, ativo, created_at, updated_at) VALUES
(NULL, 'carne_criado', 'Seu carne #{{carne_id}} foi criado - Braziliana',
'<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f6f9;font-family:Segoe UI,Tahoma,Geneva,Verdana,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f6f9;padding:30px 0;"><tr><td align="center"><table width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:8px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.08);"><tr><td style="background-color:#1a2332;padding:24px 30px;text-align:center;"><h1 style="color:#ffffff;margin:0;font-size:22px;font-weight:600;">Braziliana Shop</h1></td></tr><tr><td style="padding:30px;"><p style="font-size:16px;color:#333;margin:0 0 16px;">Ola, <strong>{{cliente_nome}}</strong>!</p><div style="background-color:#d4edda;border-left:4px solid #28a745;padding:12px 16px;margin-bottom:20px;border-radius:4px;"><p style="margin:0;color:#155724;font-size:14px;"><strong>Tudo certo!</strong> Seu carne foi criado com sucesso e esta pronto para pagamento.</p></div><p style="font-size:14px;color:#555;margin:0 0 20px;">Seu carne de <strong>{{quantidade_parcelas}}x</strong> no valor total de <strong>{{total_geral}}</strong> foi gerado para o pedido <strong>#{{pedido_id}}</strong>.</p><p style="font-size:14px;color:#555;margin:0 0 20px;">Acesse o link abaixo para visualizar suas parcelas e realizar os pagamentos:</p><table width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:10px 0 24px;"><a href="{{url_meu_carne}}" style="display:inline-block;background-color:#1a2332;color:#ffffff;text-decoration:none;padding:14px 32px;border-radius:6px;font-size:14px;font-weight:600;">Ver meu carne e pagar</a></td></tr></table><p style="font-size:13px;color:#888;margin:0;">Em caso de duvidas, entre em contato com nosso suporte.</p></td></tr><tr><td style="background-color:#f8f9fa;padding:20px 30px;text-align:center;border-top:1px solid #eee;"><p style="font-size:12px;color:#999;margin:0;">Braziliana Shop - Este e um email automatico, nao responda.</p></td></tr></table></td></tr></table></body></html>',
1, NOW(), NOW()),

(NULL, 'carne_cobranca', 'Cobranca - Parcela {{numero_parcela}}/{{total_parcelas}} do Carne #{{carne_id}}',
'<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f6f9;font-family:Segoe UI,Tahoma,Geneva,Verdana,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f6f9;padding:30px 0;"><tr><td align="center"><table width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:8px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.08);"><tr><td style="background-color:#1a2332;padding:24px 30px;text-align:center;"><h1 style="color:#ffffff;margin:0;font-size:22px;font-weight:600;">Braziliana Shop</h1></td></tr><tr><td style="padding:30px;"><p style="font-size:16px;color:#333;margin:0 0 16px;">Ola, <strong>{{cliente_nome}}</strong>!</p><div style="background-color:#f8d7da;border-left:4px solid #dc3545;padding:12px 16px;margin-bottom:20px;border-radius:4px;"><p style="margin:0;color:#721c24;font-size:14px;"><strong>Atencao:</strong> Sua parcela esta pendente de pagamento. Regularize para evitar o cancelamento do seu carne.</p></div><p style="font-size:14px;color:#555;margin:0 0 20px;">Estamos entrando em contato para lembrar sobre o pagamento da parcela do seu carne:</p><table width="100%" cellpadding="0" cellspacing="0" style="background-color:#f8f9fa;border-radius:6px;margin-bottom:24px;"><tr><td style="padding:20px;"><table width="100%" cellpadding="4" cellspacing="0"><tr><td style="font-size:13px;color:#666;padding:4px 0;">Carne:</td><td style="font-size:13px;color:#333;font-weight:600;padding:4px 0;text-align:right;">#{{carne_id}} (Pedido #{{pedido_id}})</td></tr><tr><td style="font-size:13px;color:#666;padding:4px 0;">Parcela:</td><td style="font-size:13px;color:#333;font-weight:600;padding:4px 0;text-align:right;">{{numero_parcela}} de {{total_parcelas}}</td></tr><tr><td style="font-size:13px;color:#666;padding:4px 0;">Vencimento:</td><td style="font-size:13px;color:#dc3545;font-weight:600;padding:4px 0;text-align:right;">{{vencimento}}</td></tr><tr><td colspan="2" style="border-top:1px solid #dee2e6;padding-top:8px;"></td></tr><tr><td style="font-size:13px;color:#666;padding:4px 0;">Produtos:</td><td style="font-size:13px;color:#333;padding:4px 0;text-align:right;">{{valor_produtos}}</td></tr><tr><td style="font-size:13px;color:#666;padding:4px 0;">Taxas:</td><td style="font-size:13px;color:#333;padding:4px 0;text-align:right;">{{valor_taxas}}</td></tr><tr><td style="font-size:14px;color:#333;font-weight:700;padding:8px 0 4px;">Total:</td><td style="font-size:16px;color:#1a2332;font-weight:700;padding:8px 0 4px;text-align:right;">{{valor_parcela}}</td></tr></table></td></tr></table><table width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:10px 0 24px;"><a href="{{url_meu_carne}}" style="display:inline-block;background-color:#dc3545;color:#ffffff;text-decoration:none;padding:14px 32px;border-radius:6px;font-size:14px;font-weight:600;">Pagar agora</a></td></tr></table><p style="font-size:13px;color:#888;margin:0 0 8px;">Se voce ja realizou o pagamento, desconsidere este email. O processamento pode levar ate 2 dias uteis.</p><p style="font-size:13px;color:#888;margin:0;">Em caso de duvidas, entre em contato com nosso suporte.</p></td></tr><tr><td style="background-color:#f8f9fa;padding:20px 30px;text-align:center;border-top:1px solid #eee;"><p style="font-size:12px;color:#999;margin:0;">Braziliana Shop - Este e um email automatico, nao responda.</p></td></tr></table></td></tr></table></body></html>',
1, NOW(), NOW()),

(NULL, 'carne_parcela_proxima_vencimento', 'Lembrete: parcela proxima do vencimento - Carne #{{carne_id}}',
'<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f6f9;font-family:Segoe UI,Tahoma,Geneva,Verdana,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f6f9;padding:30px 0;"><tr><td align="center"><table width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:8px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.08);"><tr><td style="background-color:#1a2332;padding:24px 30px;text-align:center;"><h1 style="color:#ffffff;margin:0;font-size:22px;font-weight:600;">Braziliana Shop</h1></td></tr><tr><td style="padding:30px;"><p style="font-size:16px;color:#333;margin:0 0 16px;">Ola, <strong>{{cliente_nome}}</strong>!</p><div style="background-color:#fff3cd;border-left:4px solid #ffc107;padding:12px 16px;margin-bottom:20px;border-radius:4px;"><p style="margin:0;color:#856404;font-size:14px;"><strong>Lembrete:</strong> Sua parcela vence em breve. Evite atrasos!</p></div><p style="font-size:14px;color:#555;margin:0 0 20px;">Sua parcela <strong>{{numero_parcela}}</strong> no valor de <strong>{{valor_parcela}}</strong> vence em <strong>{{vencimento}}</strong>.</p><p style="font-size:14px;color:#555;margin:0 0 20px;">Realize o pagamento para manter seu carne em dia e evitar cobrancas adicionais.</p><table width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:10px 0 24px;"><a href="{{url_meu_carne}}" style="display:inline-block;background-color:#ffc107;color:#333;text-decoration:none;padding:14px 32px;border-radius:6px;font-size:14px;font-weight:600;">Pagar agora</a></td></tr></table><p style="font-size:13px;color:#888;margin:0;">Em caso de duvidas, entre em contato com nosso suporte.</p></td></tr><tr><td style="background-color:#f8f9fa;padding:20px 30px;text-align:center;border-top:1px solid #eee;"><p style="font-size:12px;color:#999;margin:0;">Braziliana Shop - Este e um email automatico, nao responda.</p></td></tr></table></td></tr></table></body></html>',
1, NOW(), NOW()),

(NULL, 'carne_pagamento_confirmado', 'Pagamento confirmado - Carne #{{carne_id}}',
'<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f6f9;font-family:Segoe UI,Tahoma,Geneva,Verdana,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f6f9;padding:30px 0;"><tr><td align="center"><table width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:8px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.08);"><tr><td style="background-color:#1a2332;padding:24px 30px;text-align:center;"><h1 style="color:#ffffff;margin:0;font-size:22px;font-weight:600;">Braziliana Shop</h1></td></tr><tr><td style="padding:30px;"><p style="font-size:16px;color:#333;margin:0 0 16px;">Ola, <strong>{{cliente_nome}}</strong>!</p><div style="background-color:#d4edda;border-left:4px solid #28a745;padding:12px 16px;margin-bottom:20px;border-radius:4px;"><p style="margin:0;color:#155724;font-size:14px;"><strong>Pagamento recebido!</strong> Sua parcela <strong>{{numero_parcela}}</strong> no valor de <strong>{{valor_parcela}}</strong> foi registrada como paga.</p></div><p style="font-size:14px;color:#555;margin:0 0 20px;">Obrigado pelo pagamento! Continue mantendo seu carne em dia para liberar o envio do seu produto.</p><table width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:10px 0 24px;"><a href="{{url_meu_carne}}" style="display:inline-block;background-color:#28a745;color:#ffffff;text-decoration:none;padding:14px 32px;border-radius:6px;font-size:14px;font-weight:600;">Ver meu carne</a></td></tr></table><p style="font-size:13px;color:#888;margin:0;">Em caso de duvidas, entre em contato com nosso suporte.</p></td></tr><tr><td style="background-color:#f8f9fa;padding:20px 30px;text-align:center;border-top:1px solid #eee;"><p style="font-size:12px;color:#999;margin:0;">Braziliana Shop - Este e um email automatico, nao responda.</p></td></tr></table></td></tr></table></body></html>',
1, NOW(), NOW()),

(NULL, 'carne_quitado', 'Parabens! Carne #{{carne_id}} quitado',
'<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f6f9;font-family:Segoe UI,Tahoma,Geneva,Verdana,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f6f9;padding:30px 0;"><tr><td align="center"><table width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:8px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.08);"><tr><td style="background-color:#1a2332;padding:24px 30px;text-align:center;"><h1 style="color:#ffffff;margin:0;font-size:22px;font-weight:600;">Braziliana Shop</h1></td></tr><tr><td style="padding:30px;"><p style="font-size:16px;color:#333;margin:0 0 16px;">Ola, <strong>{{cliente_nome}}</strong>!</p><div style="background-color:#d4edda;border-left:4px solid #28a745;padding:12px 16px;margin-bottom:20px;border-radius:4px;"><p style="margin:0;color:#155724;font-size:14px;"><strong>Parabens!</strong> Todas as parcelas do seu carne <strong>#{{carne_id}}</strong> foram pagas!</p></div><p style="font-size:14px;color:#555;margin:0 0 20px;">Seu carne esta totalmente quitado. Seu produto do pedido <strong>#{{pedido_id}}</strong> sera preparado para envio em breve.</p><p style="font-size:14px;color:#555;margin:0 0 20px;">Voce recebera uma notificacao assim que o envio for liberado com as informacoes de rastreamento.</p><table width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:10px 0 24px;"><a href="{{url_meu_carne}}" style="display:inline-block;background-color:#28a745;color:#ffffff;text-decoration:none;padding:14px 32px;border-radius:6px;font-size:14px;font-weight:600;">Ver meu carne</a></td></tr></table><p style="font-size:13px;color:#888;margin:0;">Em caso de duvidas, entre em contato com nosso suporte.</p></td></tr><tr><td style="background-color:#f8f9fa;padding:20px 30px;text-align:center;border-top:1px solid #eee;"><p style="font-size:12px;color:#999;margin:0;">Braziliana Shop - Este e um email automatico, nao responda.</p></td></tr></table></td></tr></table></body></html>',
1, NOW(), NOW()),

(NULL, 'carne_envio_liberado', 'Envio liberado - Carne #{{carne_id}}',
'<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f6f9;font-family:Segoe UI,Tahoma,Geneva,Verdana,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f6f9;padding:30px 0;"><tr><td align="center"><table width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:8px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.08);"><tr><td style="background-color:#1a2332;padding:24px 30px;text-align:center;"><h1 style="color:#ffffff;margin:0;font-size:22px;font-weight:600;">Braziliana Shop</h1></td></tr><tr><td style="padding:30px;"><p style="font-size:16px;color:#333;margin:0 0 16px;">Ola, <strong>{{cliente_nome}}</strong>!</p><div style="background-color:#d4edda;border-left:4px solid #28a745;padding:12px 16px;margin-bottom:20px;border-radius:4px;"><p style="margin:0;color:#155724;font-size:14px;"><strong>Boa noticia!</strong> O envio do seu produto foi liberado!</p></div><p style="font-size:14px;color:#555;margin:0 0 20px;">O produto do seu pedido <strong>#{{pedido_id}}</strong> (Carne <strong>#{{carne_id}}</strong>) esta sendo preparado para envio.</p><p style="font-size:14px;color:#555;margin:0 0 20px;">Em breve voce recebera as informacoes de rastreamento por email.</p><table width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:10px 0 24px;"><a href="{{url_meu_carne}}" style="display:inline-block;background-color:#1a2332;color:#ffffff;text-decoration:none;padding:14px 32px;border-radius:6px;font-size:14px;font-weight:600;">Ver meu carne</a></td></tr></table><p style="font-size:13px;color:#888;margin:0;">Em caso de duvidas, entre em contato com nosso suporte.</p></td></tr><tr><td style="background-color:#f8f9fa;padding:20px 30px;text-align:center;border-top:1px solid #eee;"><p style="font-size:12px;color:#999;margin:0;">Braziliana Shop - Este e um email automatico, nao responda.</p></td></tr></table></td></tr></table></body></html>',
1, NOW(), NOW()),

(NULL, 'carne_aviso_cancelamento', 'URGENTE: Aviso de cancelamento - Carne #{{carne_id}}',
'<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f6f9;font-family:Segoe UI,Tahoma,Geneva,Verdana,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f6f9;padding:30px 0;"><tr><td align="center"><table width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:8px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.08);"><tr><td style="background-color:#dc3545;padding:24px 30px;text-align:center;"><h1 style="color:#ffffff;margin:0;font-size:22px;font-weight:600;">Braziliana Shop</h1></td></tr><tr><td style="padding:30px;"><p style="font-size:16px;color:#333;margin:0 0 16px;">Ola, <strong>{{cliente_nome}}</strong>!</p><div style="background-color:#f8d7da;border-left:4px solid #dc3545;padding:12px 16px;margin-bottom:20px;border-radius:4px;"><p style="margin:0;color:#721c24;font-size:14px;"><strong>URGENTE:</strong> Seu carne <strong>#{{carne_id}}</strong> sera <strong>cancelado</strong> se o pagamento nao for regularizado nos proximos dias.</p></div><p style="font-size:14px;color:#555;margin:0 0 20px;">Identificamos que seu carne possui parcelas em atraso ha muito tempo. Este e o ultimo aviso antes do cancelamento automatico.</p><p style="font-size:14px;color:#555;margin:0 0 8px;"><strong>O que acontece se for cancelado:</strong></p><ul style="font-size:14px;color:#555;margin:0 0 20px;padding-left:20px;"><li>O carne sera encerrado definitivamente</li><li>Os valores ja pagos nao serao reembolsados</li><li>O produto nao sera enviado</li></ul><p style="font-size:14px;color:#555;margin:0 0 20px;">Entre em contato conosco se precisar de ajuda ou se deseja negociar as parcelas em atraso.</p><table width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:10px 0 24px;"><a href="{{url_meu_carne}}" style="display:inline-block;background-color:#dc3545;color:#ffffff;text-decoration:none;padding:14px 32px;border-radius:6px;font-size:14px;font-weight:600;">Regularizar agora</a></td></tr></table><p style="font-size:13px;color:#888;margin:0;">Em caso de duvidas, entre em contato com nosso suporte.</p></td></tr><tr><td style="background-color:#f8f9fa;padding:20px 30px;text-align:center;border-top:1px solid #eee;"><p style="font-size:12px;color:#999;margin:0;">Braziliana Shop - Este e um email automatico, nao responda.</p></td></tr></table></td></tr></table></body></html>',
1, NOW(), NOW()),

(NULL, 'carne_cancelado', 'Carne #{{carne_id}} cancelado por inadimplencia',
'<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#f4f6f9;font-family:Segoe UI,Tahoma,Geneva,Verdana,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f6f9;padding:30px 0;"><tr><td align="center"><table width="600" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:8px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.08);"><tr><td style="background-color:#1a2332;padding:24px 30px;text-align:center;"><h1 style="color:#ffffff;margin:0;font-size:22px;font-weight:600;">Braziliana Shop</h1></td></tr><tr><td style="padding:30px;"><p style="font-size:16px;color:#333;margin:0 0 16px;">Ola, <strong>{{cliente_nome}}</strong>.</p><div style="background-color:#f8d7da;border-left:4px solid #dc3545;padding:12px 16px;margin-bottom:20px;border-radius:4px;"><p style="margin:0;color:#721c24;font-size:14px;"><strong>Cancelado:</strong> Seu carne <strong>#{{carne_id}}</strong> foi cancelado por falta de pagamento.</p></div><p style="font-size:14px;color:#555;margin:0 0 20px;">Infelizmente, devido a inadimplencia prolongada, seu carne referente ao pedido <strong>#{{pedido_id}}</strong> foi cancelado automaticamente.</p><p style="font-size:14px;color:#555;margin:0 0 20px;">Se voce acredita que houve um erro ou deseja mais informacoes, entre em contato com nosso suporte.</p><p style="font-size:13px;color:#888;margin:0;">Em caso de duvidas, entre em contato com nosso suporte.</p></td></tr><tr><td style="background-color:#f8f9fa;padding:20px 30px;text-align:center;border-top:1px solid #eee;"><p style="font-size:12px;color:#999;margin:0;">Braziliana Shop - Este e um email automatico, nao responda.</p></td></tr></table></td></tr></table></body></html>',
1, NOW(), NOW());
